(7537847, 1206118, 65234, '<td valign="top">Hi, Bruce! Love seeing a fully feathered Grey :-) I note you bite, but then, you''re a bird, and that''s what birds do.</td>', 'Hi, Bruce! Love seeing a fully feathered Grey :-) I note you bite, but then, you''re a bird, and that''s what birds do.', '2017-10-04 14:06:51.000000', NULL, 1),
(7537848, 1206032, 65234, '<td valign="top">Now you''ve made me sad. Stuck in that boring bag while the swirl of color that is life goes on around him.</td>', 'Now you''ve made me sad. Stuck in that boring bag while the swirl of color that is life goes on around him.', '2017-10-04 14:09:40.000000', NULL, 1),
(7537849, 1206182, 65234, '<td valign="top">Love the title, and the image. He looks like a little alien listening to instructions from his leader.</td>', 'Love the title, and the image. He looks like a little alien listening to instructions from his leader.', '2017-10-04 14:11:08.000000', NULL, 1),
